public class HistoricalPersonData {

    public static final List<Person> PEOPLE = List.of(

            // ==================================================
            // 고려
            // ==================================================
            // 918년(고려 건국) 이전 왕조·인물은 서비스 대상에서 제외한다(팀 결정).
            // 연표(korean-history-chronology.xml)도 918년부터 시작한다.

            new Person("태조 왕건", "송악의 호족 출신으로 궁예의 휘하에서 세력을 키운 뒤 918년 궁예를 몰아내고 고려를 건국했다. 이후 후백제와 신라를 상대로 군사와 외교를 병행해 936년 후삼국을 통일했다. 호족 세력을 포용하기 위해 혼인 정책과 사성 정책 등을 활용했으며, 북진 정책을 추진해 고려의 영토와 국가적 정체성을 확립했다.", "고려를 세운 건국자", Kingdom.GORYEO, PersonType.KING, 918, 943),
            new Person("광종", "고려 제4대 왕으로, 즉위 후 강력한 왕권 강화 정책을 추진해 호족 세력의 영향력을 약화시켰다. 노비안검법을 실시해 불법적으로 노비가 된 사람들을 양인으로 되돌렸으며, 과거제를 도입해 능력에 따라 관료를 선발하는 기반을 마련했다. 황제국 체제를 표방하고 독자적인 연호를 사용하는 등 왕권 중심의 중앙집권 체제를 강화했다.", "왕권을 강화한 고려의 왕", Kingdom.GORYEO, PersonType.KING, 949, 975),
            new Person("공민왕", "고려 후기 원나라의 간섭에서 벗어나 국가의 자주성을 회복하기 위해 적극적인 개혁 정책을 추진했다. 원나라의 영향력을 제거하고 쌍성총관부를 되찾는 등 영토 회복에도 힘썼다. 신돈을 등용해 전민변정도감을 설치하고 권문세족이 불법으로 차지한 토지와 노비 문제를 바로잡으려 했지만, 개혁 과정에서 정치적 갈등이 심화되었다.", "개혁을 추진한 고려의 왕", Kingdom.GORYEO, PersonType.KING, 1351, 1374),
            new Person("서희", "고려의 대표적인 외교가이자 문신으로, 거란의 소손녕이 이끄는 군대가 고려를 침입한 993년 거란의 1차 침입 당시 뛰어난 외교 협상을 벌였다. 거란이 고려를 공격한 이유를 분석하고 고려가 고구려의 계승 국가임을 강조하면서 송과의 관계를 끊고 거란과 교류하겠다는 논리를 펼쳤다. 그 결과 전쟁을 크게 확대하지 않고 강동 6주를 확보하는 외교적 성과를 거두었다.", "외교 담판으로 강동 6주를 얻은 문신", Kingdom.GORYEO, PersonType.POLITICIAN, 942, 998),
            new Person("강감찬", "고려의 문신이자 장군으로, 거란의 세 차례 침입 중 1018년 제3차 침입 당시 고려군을 지휘했다. 적군을 귀주로 유인한 뒤 결정적인 공격을 가해 거란군을 크게 격파했으며, 이 전투가 귀주대첩이다. 뛰어난 지휘 능력으로 고려의 국토를 지켜냈으며, 이후 거란과 고려 사이에 장기간의 평화가 유지되는 데 기여했다.", "귀주대첩을 이끈 명장", Kingdom.GORYEO, PersonType.GENERAL, 948, 1031),
            new Person("최무선", "고려 말 왜구의 침입에 대응하기 위해 화약과 화약 무기의 개발에 힘쓴 과학기술자이자 무관이다. 중국에서 화약 제조 기술을 습득한 뒤 고려에서 화약을 직접 제조하는 데 성공하고 화통도감 설치를 주도했다. 화포를 활용해 1380년 진포대첩에서 왜구의 함선을 격파하는 데 기여했으며, 고려의 군사 기술 발전에 큰 영향을 미쳤다.", "화약 무기를 개발한 발명가", Kingdom.GORYEO, PersonType.INVENTOR, 1325, 1395),

            // ==================================================
            // 조선 - 왕
            // ==================================================

            new Person("태조", "고려 말 무장으로 성장해 왜구와 홍건적을 격퇴하며 군사적 명성을 쌓았다. 1388년 위화도 회군을 계기로 정치적 실권을 장악한 뒤 개혁 세력과 함께 고려 왕조를 무너뜨리고 1392년 조선을 건국했다. 즉위 후 한양 천도를 추진하고 새로운 국가 체제를 정비하며 조선 왕조의 기틀을 마련했다.", "조선을 건국한 초대 왕", Kingdom.JOSEON, PersonType.KING, 1392, 1398),
            new Person("정종", "태조 이성계의 둘째 아들로, 1398년 제1차 왕자의 난 이후 왕위에 올랐다. 그러나 실제 정치적 실권은 동생 이방원에게 있었으며, 왕권을 둘러싼 형제간 갈등 속에서 재위 기간이 짧았다. 1400년 제2차 왕자의 난 이후 이방원에게 왕위를 양위하고 상왕으로 물러났다.", "조선 제2대 왕", Kingdom.JOSEON, PersonType.KING, 1398, 1400),
            new Person("태종", "태조의 다섯째 아들 이방원으로, 두 차례 왕자의 난을 통해 정치적 실권을 장악하고 조선 제3대 왕으로 즉위했다. 사병을 혁파하고 호패법을 실시했으며 육조직계제를 시행해 국왕 중심의 행정 체계를 강화했다. 왕권을 강화하고 중앙집권적 국가 체제를 확립해 뒤를 이은 세종이 안정적으로 통치할 수 있는 기반을 마련했다.", "왕권을 강화한 조선 제3대 왕", Kingdom.JOSEON, PersonType.KING, 1400, 1418),
            new Person("세종", "조선 제4대 왕으로, 정치·경제·과학·문화 등 다양한 분야에서 국가 발전을 이끌었다. 집현전을 중심으로 학문 연구를 장려하고 훈민정음을 창제해 백성들이 쉽게 글을 사용할 수 있는 기반을 마련했다. 측우기와 앙부일구, 자격루 등 과학 기구 개발을 지원했으며 4군 6진을 개척해 북방 영토를 확장하는 등 조선의 전성기를 이끈 대표적인 군주이다.", "훈민정음을 창제한 조선 제4대 왕", Kingdom.JOSEON, PersonType.KING, 1418, 1450),
            new Person("문종", "세종의 장남으로, 세자 시절부터 오랫동안 국정에 참여하며 아버지의 통치를 보좌했다. 학문과 과학기술에 관심이 많았으며 측우기와 천문 관측 등 여러 분야의 발전에도 관여했다. 즉위 후에는 세종 대의 정책을 계승했지만 병약한 건강으로 인해 약 2년 만에 세상을 떠났고, 어린 아들 단종에게 왕위를 물려주었다.", "조선 제5대 왕", Kingdom.JOSEON, PersonType.KING, 1450, 1452),
            new Person("단종", "문종의 아들로 12세의 어린 나이에 조선 제6대 왕으로 즉위했다. 어린 왕을 대신해 김종서 등 대신들이 국정을 운영했으나, 숙부 수양대군이 계유정난을 일으켜 실권을 장악했다. 결국 왕위를 빼앗기고 상왕으로 물러났으며, 이후 유배되어 1457년 세상을 떠났다. 조선 왕실의 권력 투쟁 속에서 비극적인 운명을 맞은 왕으로 기억된다.", "숙부에게 왕위를 빼앗긴 비운의 왕", Kingdom.JOSEON, PersonType.KING, 1452, 1455),
            new Person("세조", "수양대군으로서 계유정난을 일으켜 김종서 등 정적을 제거하고 조카 단종을 압박해 왕위를 차지했다. 즉위 후 왕권을 강화하기 위해 의정부의 권한을 제한하고 육조직계제를 시행했으며, 국가의 법전인 경국대전 편찬을 시작했다. 강력한 통치 체제를 구축하는 성과를 남겼지만 조카의 왕위를 빼앗았다는 점에서 역사적으로 논란이 많은 군주이다.", "계유정난으로 즉위한 조선 제7대 왕", Kingdom.JOSEON, PersonType.KING, 1455, 1468),
            new Person("예종", "세조의 둘째 아들로 조선 제8대 왕에 즉위했으나 병약한 건강 때문에 재위 기간이 1년여에 그쳤다. 세조 대부터 추진된 국가 제도와 법전 정비 작업을 이어갔으며, 남이의 옥사 등 정치적 사건이 발생한 시기를 통치했다. 짧은 재위 기간으로 인해 큰 규모의 정책을 추진하기는 어려웠다.", "조선 제8대 왕", Kingdom.JOSEON, PersonType.KING, 1468, 1469),
            new Person("성종", "조선 제9대 왕으로, 세조 대부터 편찬이 진행되던 경국대전을 완성하고 반포해 조선의 통치 체계와 법제도를 확립했다. 홍문관을 설치하고 사림 세력을 등용하며 학문과 유교 정치의 발전을 장려했다. 국가의 주요 제도와 문물을 정비하면서 조선 전기의 안정적인 통치 체제를 완성한 왕으로 평가받는다.", "경국대전을 완성한 조선 제9대 왕", Kingdom.JOSEON, PersonType.KING, 1469, 1494),
            new Person("연산군", "조선 제10대 왕으로, 즉위 초기에는 비교적 정상적인 정치를 펼쳤으나 점차 권력을 남용하고 신하들을 대규모로 숙청했다. 무오사화와 갑자사화를 일으켜 사림과 대신들을 탄압했으며, 사치와 향락을 일삼아 민심을 크게 잃었다. 결국 1506년 중종반정으로 왕위에서 폐위되어 군호를 받은 채 유배지에서 생을 마쳤다.", "폭정으로 폐위된 조선 제10대 왕", Kingdom.JOSEON, PersonType.KING, 1494, 1506),
            new Person("중종", "연산군을 몰아낸 중종반정을 통해 조선 제11대 왕으로 즉위했다. 개혁적인 유학자 조광조를 등용해 현량과 실시와 향약 보급 등 정치 개혁을 추진했으나, 조광조를 비롯한 사림 세력이 기묘사화로 숙청되면서 개혁은 좌절되었다. 재위 기간 동안 훈구와 사림의 정치적 대립이 이어졌으며 삼포왜란 등 대외적인 문제에도 대응했다.", "반정으로 즉위한 조선 제11대 왕", Kingdom.JOSEON, PersonType.KING, 1506, 1544),
            new Person("인종", "중종의 장남으로 조선 제12대 왕에 즉위했다. 어린 시절부터 학문과 유교적 덕목을 중시하고 어머니 장경왕후에 대한 효심이 깊었던 것으로 알려져 있다. 그러나 즉위 후 건강이 급격히 악화되어 불과 8개월 만에 세상을 떠났으며, 짧은 재위 기간으로 인해 본격적인 정치 개혁을 추진하지 못했다.", "조선 제12대 왕", Kingdom.JOSEON, PersonType.KING, 1544, 1545),
            new Person("명종", "인종의 뒤를 이어 어린 나이에 즉위했으며, 어머니 문정왕후가 수렴청정을 하면서 외척 세력이 정치적 영향력을 크게 행사했다. 을사사화와 양재역 벽서 사건 등 정치적 숙청이 이어졌으며, 을묘왜변 등 외적의 침입에도 대응해야 했다. 문정왕후가 사망한 뒤 직접 정치를 펼치려 했으나 재위 기간이 길지 않았다.", "조선 제13대 왕", Kingdom.JOSEON, PersonType.KING, 1545, 1567),
            new Person("선조", "조선 제14대 왕으로 재위 기간 동안 붕당 정치가 본격적으로 형성되었으며, 1592년 일본의 침략으로 임진왜란이 발생했다. 전쟁 초기에는 수도와 국토 대부분이 큰 피해를 입었지만 이순신이 이끄는 수군과 전국 각지의 의병 활동, 명나라의 지원 등을 통해 일본군의 침략을 막아냈다. 전쟁 이후 피폐해진 국가를 재건하는 과제를 남겼다.", "임진왜란을 겪은 조선 제14대 왕", Kingdom.JOSEON, PersonType.KING, 1567, 1608),
            new Person("광해군", "임진왜란 이후 혼란스러운 국가를 안정시키기 위해 토지와 세금 제도를 정비하고 대동법을 시행했다. 외교적으로는 명나라와 후금 사이에서 실리적인 중립 외교를 추진해 후금의 성장으로 인한 전쟁을 피하려 했다. 그러나 정치적 갈등이 심화되면서 1623년 인조반정으로 왕위에서 쫓겨났으며, 이후 폐위된 군주로 남게 되었다.", "실리 외교를 펼친 조선 제15대 왕", Kingdom.JOSEON, PersonType.KING, 1608, 1623),
            new Person("인조", "인조반정을 통해 광해군을 몰아내고 왕위에 오른 조선 제16대 왕이다. 친명배금 정책을 추진하면서 후금과의 관계가 악화되어 정묘호란과 병자호란을 겪었다. 특히 1637년 병자호란 당시 청나라 군대에 항복하고 삼전도에서 청 태종에게 굴욕적인 항복 의식을 치렀으며, 전쟁 이후 조선의 외교 관계와 정치에 큰 변화가 나타났다.", "병자호란을 겪은 조선 제16대 왕", Kingdom.JOSEON, PersonType.KING, 1623, 1649),
            new Person("효종", "병자호란 이후 청나라에 볼모로 끌려갔다가 귀국해 조선 제17대 왕으로 즉위했다. 청나라에 대한 복수와 국력 회복을 목표로 북벌론을 추진하고 군사력을 강화했지만 실제 대규모 북벌은 실행하지 못했다. 군사 제도를 정비하고 국방력을 강화하는 한편 경제와 사회를 안정시키기 위한 정책도 추진했다.", "북벌을 추진한 조선 제17대 왕", Kingdom.JOSEON, PersonType.KING, 1649, 1659),
            new Person("현종", "효종의 뒤를 이어 즉위한 조선 제18대 왕으로, 재위 기간 동안 왕실의 상복 문제를 둘러싼 예송논쟁이 두 차례 발생했다. 서인과 남인 사이의 정치적 갈등이 심화되면서 붕당 정치가 더욱 복잡해졌으며, 이러한 정치적 대립 속에서 왕권을 유지하려 했다. 국방과 경제 회복에도 관심을 기울이며 전후 국가 재건을 이어갔다.", "조선 제18대 왕", Kingdom.JOSEON, PersonType.KING, 1659, 1674),
            new Person("숙종", "조선 제19대 왕으로, 정치 세력을 교체하는 환국을 반복적으로 활용해 붕당 사이의 균형을 조정하고 왕권을 강화했다. 경신환국, 기사환국, 갑술환국 등을 통해 정국을 주도했으며, 대동법을 전국적으로 확대하고 상평통보의 유통을 활성화하는 등 경제 정책도 추진했다. 강력한 왕권을 바탕으로 조선 후기 정치 질서에 큰 영향을 미쳤다.", "왕권을 강화한 조선 제19대 왕", Kingdom.JOSEON, PersonType.KING, 1674, 1720),
            new Person("경종", "숙종의 장남으로 조선 제20대 왕에 즉위했으나 병약한 건강과 노론·소론 사이의 극심한 정치적 대립 속에서 국정을 운영했다. 즉위 과정에서 세자 시절부터 이어진 왕위 계승 문제를 둘러싸고 정치적 갈등이 심화되었다. 재위 4년 만에 세상을 떠나면서 동생 연잉군이 영조로 즉위하게 되었다.", "조선 제20대 왕", Kingdom.JOSEON, PersonType.KING, 1720, 1724),
            new Person("영조", "조선 제21대 왕으로 52년 동안 재위하며 조선 왕 가운데 가장 긴 재위 기간을 기록했다. 붕당 간 갈등을 완화하기 위해 탕평책을 추진하고 균역법을 실시하는 등 국가 제도와 민생을 안정시키려 했다. 한편 아들 사도세자를 뒤주에 가두어 죽게 한 사건은 그의 통치 기간을 대표하는 비극적인 사건으로 남아 있다.", "탕평책을 편 조선 제21대 왕", Kingdom.JOSEON, PersonType.KING, 1724, 1776),
            new Person("정조", "조선 제22대 왕으로 즉위한 뒤 아버지 사도세자의 명예를 회복하고 왕권을 강화하기 위한 개혁 정책을 추진했다. 규장각을 설치해 학문과 정책 연구를 장려하고 인재를 등용했으며, 수원 화성을 건설해 군사적·경제적 기반을 강화했다. 탕평책을 계승하면서 실학자들을 비롯한 다양한 인재를 활용해 조선 후기 문화와 정치의 발전을 이끌었다.", "개혁을 추진한 조선 제22대 왕", Kingdom.JOSEON, PersonType.KING, 1776, 1800),
            new Person("순조", "조선 제23대 왕으로 11세의 어린 나이에 즉위해 정순왕후의 수렴청정을 받았다. 이후 안동 김씨 등 외척 가문이 정권을 장악하는 세도정치가 본격적으로 전개되었으며, 정치적 부패와 사회적 불안이 심화되었다. 홍경래의 난이 발생하는 등 민생 문제가 커졌고, 천주교 박해 등 사회·종교적 갈등도 이어졌다.", "조선 제23대 왕", Kingdom.JOSEON, PersonType.KING, 1800, 1834),
            new Person("헌종", "순조의 뒤를 이어 어린 나이에 즉위한 조선 제24대 왕으로, 재위 기간 동안 세도정치가 계속되었다. 외척 세력이 정치를 주도하는 상황에서 왕권을 충분히 행사하기 어려웠으며, 천주교에 대한 탄압이 이어져 1839년 기해박해가 발생했다. 재위 기간이 짧고 정치적 영향력이 제한적이었던 군주로 평가된다.", "조선 제24대 왕", Kingdom.JOSEON, PersonType.KING, 1834, 1849),
            new Person("철종", "왕실의 가까운 후계자가 부족한 상황에서 강화도에서 평민과 다름없이 생활하던 이원범이 왕위에 올라 조선 제25대 왕이 되었다. 그래서 '강화도령'이라는 별칭으로도 알려져 있다. 왕위에 오른 뒤에도 안동 김씨를 중심으로 한 세도정치가 계속되어 실질적인 왕권을 행사하기 어려웠으며, 삼정의 문란 등 사회적 문제가 심각해졌다.", "강화도령으로 불린 조선 제25대 왕", Kingdom.JOSEON, PersonType.KING, 1849, 1863),
            new Person("고종", "조선 제26대 왕으로 어린 나이에 즉위해 아버지 흥선대원군의 섭정을 받았다. 이후 개항과 서양 문물의 유입 속에서 근대화를 추진했으며, 갑오개혁과 대한제국 수립 등 격변하는 국제 정세에 대응했다. 1897년 대한제국을 선포하고 황제로 즉위해 국가의 독립과 자주성을 강조했지만, 일본의 영향력이 확대되면서 국권을 지키기 위해 어려운 외교적 상황에 놓였다.", "조선 제26대 왕이자 대한제국 초대 황제", Kingdom.JOSEON, PersonType.KING, 1863, 1897),
            new Person("순종", "고종의 아들로 대한제국 제2대 황제에 즉위했으며, 즉위 당시 이미 일본의 강한 정치적 압박을 받고 있었다. 1907년 헤이그 특사 사건 이후 고종이 강제 퇴위하면서 황제가 되었지만 실질적인 통치 권한은 크게 제한되어 있었다. 1910년 한일병합조약으로 대한제국이 일본에 병합되면서 군주로서의 지위를 잃었고, 조선 왕조의 마지막 군주가 되었다.", "조선의 마지막 왕", Kingdom.JOSEON, PersonType.KING, 1907, 1910),

            // ==================================================
            // 조선 - 주요 인물
            // ==================================================

            // ==================================================
            // 대한제국
            // ==================================================
            // 고종은 조선 국왕(1863~1897)과 대한제국 황제(1897~1907)라는 서로 다른 두 국가·직위를
            // 거쳤으므로, PersonPlaceMapping/PersonImageData가 (이름, 국가) 조합으로 두 시기를
            // 구분해 참조할 수 있도록 kingdom별로 별도 행을 둔다(위 JOSEON 항목과는 별개 인물 행).
            new Person("고종", "1897년 대한제국을 선포하고 초대 황제로 즉위해 국호를 조선에서 대한제국으로 바꾸고 자주적인 근대 국가 체제를 구축하고자 했다. 환구단에서 황제 즉위식을 거행하며 자주독립을 대내외에 알렸으나, 일본의 내정 간섭이 갈수록 심해지는 가운데 헤이그에 특사를 파견해 을사늑약의 부당함을 알리려 했다. 이 사건을 빌미로 1907년 일본에 의해 강제 퇴위되면서 황제위에서 물러났다.", "대한제국을 선포한 초대 황제", Kingdom.KOREAN_EMPIRE, PersonType.KING, 1897, 1907),

            new Person("이순신", "임진왜란 당시 조선 수군을 지휘한 대표적인 장군으로, 일본군의 해상 보급로를 차단하며 전쟁의 흐름을 바꾸는 데 결정적인 역할을 했다. 한산도대첩에서 학익진 전법을 활용해 일본 수군을 크게 격파했으며, 원균의 패전 이후 다시 수군을 이끌어 명량해전에서 열세한 전력으로 대승을 거두었다. 1598년 노량해전에서 일본군을 추격하던 중 전사했으며, 이후 조선을 구한 명장으로 추앙받고 있다.", "임진왜란을 승리로 이끈 명장", Kingdom.JOSEON, PersonType.GENERAL, 1576, 1598),
            new Person("장영실", "조선 전기의 대표적인 과학기술자로, 신분이 낮았음에도 세종의 능력 있는 인재 등용 정책에 힘입어 관직에 올랐다. 천문 관측과 시간 측정을 위한 기구를 개발했으며, 측우기와 앙부일구, 자격루 등 조선의 과학기술 발전에 중요한 기구를 제작했다. 조선의 천문학과 농업, 시간 측정 기술을 발전시키는 데 크게 기여한 인물로 평가된다.", "세종 대의 과학 기술자", Kingdom.JOSEON, PersonType.INVENTOR, 1400, 1450),
            new Person("허준", "조선 중기의 의관으로 선조와 광해군 시기에 왕실의 의료를 담당했다. 임진왜란 이후 백성들의 질병 치료에 도움이 될 수 있는 의학 지식을 정리하기 위해 국가적인 의학서 편찬 사업에 참여했으며, 동의보감을 완성했다. 동의보감은 질병의 원인과 치료법, 약재 등을 체계적으로 정리한 의학서로 이후 한국 전통 의학 발전에 큰 영향을 미쳤다.", "동의보감을 편찬한 의학자", Kingdom.JOSEON, PersonType.SCHOLAR, 1569, 1615),
            new Person("정약용", "조선 후기의 대표적인 실학자로, 정치·경제·사회 제도의 개혁을 주장하고 다양한 분야의 학문을 연구했다. 목민심서와 경세유표, 흠흠신서 등을 저술해 지방 행정과 국가 제도의 개선 방향을 제시했다. 수원 화성 축조 과정에서는 거중기를 고안하는 등 실용적인 기술에도 관심을 보였으며, 조선 후기 실학을 집대성한 학자로 평가받는다.", "실학을 집대성한 학자", Kingdom.JOSEON, PersonType.SCHOLAR, 1762, 1836),
            new Person("이황", "퇴계라는 호로 잘 알려진 조선 중기의 성리학자로, 인간의 마음과 도덕적 수양에 관한 철학을 깊이 연구했다. 주자학을 조선의 현실에 맞게 발전시키고 이기론을 중심으로 독자적인 학문 체계를 구축했다. 도산서원을 세워 후학을 양성했으며, 이후 조선 성리학의 발전에 큰 영향을 미친 대표적인 학자로 평가된다.", "조선을 대표하는 성리학자", Kingdom.JOSEON, PersonType.SCHOLAR, 1501, 1570),
            new Person("이이", "율곡이라는 호로 알려진 조선 중기의 대표적인 성리학자이자 정치가이다. 이황과 함께 조선 성리학을 대표하는 학자로 꼽히며, 이기론을 발전시키고 현실 문제에 적극적으로 대응해야 한다고 주장했다. 십만양병설을 비롯해 국방력 강화와 사회 개혁의 필요성을 제시했으며, 관직에 있으면서도 다양한 개혁 정책을 건의했다.", "조선을 대표하는 성리학자", Kingdom.JOSEON, PersonType.SCHOLAR, 1536, 1584),

            // ==================================================
            // 개화기
            // ==================================================

            new Person("명성황후", "고종의 왕비로, 조선이 개항과 근대화를 겪던 시기에 왕실의 정치와 외교에 깊이 관여했다. 일본의 영향력이 확대되는 상황에서 러시아 등 다른 열강과의 외교 관계를 활용해 일본의 세력 확대를 견제하려 했다. 1895년 일본 세력이 경복궁에 침입해 명성황후를 시해한 을미사변이 발생했으며, 이후 조선 말기의 대표적인 역사적 인물로 기억되고 있다.", "개화기 대한제국의 왕비", Kingdom.JOSEON, PersonType.POLITICIAN, 1866, 1895),

            // ==================================================
            // 일제강점기
            // ==================================================

            new Person("안중근", "대한제국 말기와 일제강점기 초기의 대표적인 독립운동가로, 1909년 하얼빈역에서 대한제국 침략과 동아시아 지배를 주도한 이토 히로부미를 저격했다. 체포된 이후 뤼순 감옥에서 재판을 받았으며, 옥중에서도 동양 평화와 조선의 독립에 대한 자신의 생각을 정리했다. 1910년 순국했으며, 하얼빈 의거를 통해 한국의 독립 의지를 국제사회에 알린 인물로 평가받는다.", "하얼빈에서 의거를 일으킨 독립운동가", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1905, 1910),
            new Person("유관순", "일제강점기 대표적인 독립운동가로, 1919년 3·1 운동이 전국적으로 확산되던 시기에 고향인 천안 아우내 장터에서 만세운동을 주도했다. 시위 과정에서 체포되어 서대문형무소에 수감된 뒤에도 독립 만세를 외치며 저항을 이어갔다. 옥중에서 가혹한 고문을 받았으며 1920년 순국해 3·1 운동과 한국의 독립 의지를 상징하는 인물로 기억되고 있다.", "3·1 운동을 이끈 독립운동가", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1919, 1920),
            new Person("김구", "일제강점기 대한민국 임시정부에서 활동한 대표적인 독립운동가이자 정치 지도자이다. 상하이 대한민국 임시정부의 주석을 지냈으며, 한인애국단을 조직해 이봉창과 윤봉길 등의 의거를 지원했다. 광복 이후에는 남북 분단을 막고 통일된 정부를 수립하기 위해 노력했으며, 1949년 암살될 때까지 민족의 통일과 독립을 위한 활동을 이어갔다.", "대한민국 임시정부를 이끈 지도자", Kingdom.JAPANESE_COLONY, PersonType.POLITICIAN, 1919, 1945),
            new Person("윤봉길", "충청남도 예산 출신의 독립운동가로, 김구가 조직한 한인애국단에 가입해 항일 의거에 나섰다. 1932년 4월 29일 상하이 훙커우공원에서 열린 일본군 전승 기념식장에 폭탄을 던져 일본군 수뇌부에 큰 타격을 입혔다. 거사 직후 체포되어 그해 순국했으며, 그의 의거는 침체됐던 대한민국 임시정부의 활동에 새로운 힘을 불어넣은 계기가 되었다.", "훙커우공원 의거를 일으킨 독립운동가", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1930, 1932),
            new Person("이봉창", "서울 출신의 독립운동가로, 김구가 이끄는 한인애국단의 첫 단원으로 활동했다. 1932년 1월 도쿄에서 일왕이 탄 행렬에 폭탄을 던지는 의거를 감행했으나 목표를 명중시키지는 못했고, 곧 체포되어 그해 순국했다. 비록 거사는 실패했지만 일본의 심장부에서 벌인 의거로 한국의 독립 의지를 국제사회에 알렸다.", "도쿄에서 의거를 일으킨 독립운동가", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1931, 1932),
            new Person("안창호", "호는 도산으로, 실력 양성을 통한 독립을 강조한 대표적인 독립운동가이자 교육자이다. 신민회와 흥사단을 조직해 민족의 실력을 기르고자 했으며, 대한민국 임시정부에서도 핵심적인 역할을 담당했다. 국내외를 오가며 교육과 계몽, 독립운동 조직화에 힘썼고 여러 차례 투옥된 끝에 1938년 순국했다.", "실력 양성 운동을 이끈 독립운동가", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1907, 1938),
            new Person("신채호", "역사학자이자 언론인, 독립운동가로 민족주의 사관에 입각한 역사 연구로 민족의식을 일깨웠다. '조선상고사' 등을 저술해 한국 고대사를 새롭게 정리했으며, 의열단의 요청으로 '조선혁명선언'을 작성해 무장 투쟁의 정당성을 밝혔다. 이후 무정부주의 운동에 가담했다가 체포되어 뤼순 감옥에서 순국했다.", "민족사관을 세운 역사가이자 독립운동가", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1905, 1936),
            new Person("홍범도", "대한독립군을 이끈 독립운동가이자 군사 지도자로, 뛰어난 유격 전술로 일본군에 맞섰다. 1920년 봉오동에서 일본군을 크게 격파한 봉오동 전투를 승리로 이끌었으며, 이어진 청산리 대첩에도 참여했다. 이후 연해주와 중앙아시아로 이주해 활동했으며, 봉오동 전투의 영웅으로 기억되고 있다.", "봉오동 전투를 승리로 이끈 독립군 지도자", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1919, 1921),
            new Person("김좌진", "북로군정서를 이끈 독립운동가이자 군사 지도자로, 만주 지역에서 무장 독립 투쟁을 전개했다. 1920년 청산리 일대에서 벌어진 여러 전투에서 일본군을 크게 격파한 청산리 대첩을 지휘했다. 이후에도 만주에서 독립군 조직을 이끌며 항일 무장 투쟁을 이어갔으며, 대표적인 무장 독립운동 지도자로 평가받는다.", "청산리 대첩을 이끈 독립군 지도자", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1919, 1930),
            new Person("김원봉", "의열단을 조직해 일제 요인 암살과 주요 시설 파괴 등 무장 투쟁을 주도한 독립운동가이다. 이후 조선의용대를 창설하고 대한민국 임시정부의 군사 활동에도 참여하는 등 항일 무장 투쟁의 중심에서 활동했다. 광복 이후의 행적으로 오랫동안 평가가 엇갈렸으나, 일제강점기 무장 독립운동을 대표하는 인물로 꼽힌다.", "의열단을 이끈 무장 독립운동가", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1919, 1945),
            new Person("한용운", "호는 만해로, 승려이자 시인이며 독립운동가로 활동했다. 1919년 3·1 운동 당시 민족대표 33인의 한 사람으로 참여해 독립선언에 앞장섰으며, 이 일로 투옥되었다. 시집 '님의 침묵'을 통해 저항 정신과 민족의식을 문학으로 표현했고, 불교 개혁 운동에도 힘썼다.", "3·1 운동에 참여한 승려이자 시인", Kingdom.JAPANESE_COLONY, PersonType.MONK, 1919, 1944),
            new Person("윤동주", "일제강점기 후반에 활동한 시인으로, 식민지 현실 속에서 느낀 고뇌와 저항 의식을 서정적인 시로 표현했다. '서시', '별 헤는 밤' 등 대표작을 남겼으며, 일본 유학 중 독립운동 혐의로 체포되어 후쿠오카 형무소에서 옥사했다. 광복 이후 유고 시집이 출간되어 저항 시인으로 널리 사랑받고 있다.", "저항 정신을 노래한 시인", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1938, 1945),
            new Person("이육사", "본명은 이원록으로, 시인이자 독립운동가로 활동했다. 의열단에 가담해 무장 투쟁에 참여하는 한편, '광야', '절정' 등 강렬한 저항 정신을 담은 시를 남겼다. 여러 차례 투옥되었으며 베이징 감옥에서 순국했고, 문학과 독립운동을 함께 실천한 인물로 평가받는다.", "저항시를 남긴 시인이자 독립운동가", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1927, 1944),
            new Person("이회영", "명문가 출신으로 전 재산을 처분해 만주로 망명한 뒤 독립운동에 헌신한 독립운동가이다. 신흥무관학교를 세워 독립군 간부와 인재를 양성했으며, 이후 무정부주의 운동에도 참여했다. 안락한 삶을 버리고 독립운동에 모든 것을 바친 노블레스 오블리주의 상징으로 기억되고 있다.", "신흥무관학교를 세운 독립운동가", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1910, 1932),
            new Person("지청천", "만주와 중국 지역에서 무장 독립 투쟁을 이끈 군사 지도자로, 한국독립군을 지휘해 일본군에 맞섰다. 이후 대한민국 임시정부 산하 한국광복군의 총사령관을 맡아 연합군과 협력하며 국내 진공 작전을 준비했다. 일제강점기 무장 독립운동을 대표하는 군사 지도자 중 한 사람으로 평가받는다.", "한국광복군을 이끈 군사 지도자", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1920, 1945),
            new Person("박열", "일본 도쿄에서 활동한 무정부주의 계열의 독립운동가로, 일제의 지배에 정면으로 맞섰다. 1923년 일왕 부자를 대상으로 한 폭탄 계획 혐의로 체포되어 부인 가네코 후미코와 함께 재판을 받았으며, 법정에서도 당당하게 일제를 규탄했다. 오랜 기간 투옥되었다가 광복 후 석방되었으며, 일제에 굴하지 않은 저항 정신으로 기억된다.", "일본에서 일제에 맞선 독립운동가", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1923, 1945),
            new Person("남자현", "만주 지역에서 활동한 대표적인 여성 독립운동가로, 무장 투쟁과 독립운동 조직 지원에 힘썼다. 여러 독립운동 단체와 연계해 활동했으며, 일제 요인 처단을 시도하는 등 적극적인 항일 투쟁을 전개했다. 체포된 뒤 옥중 단식으로 저항하다 순국했으며, '여성 안중근'으로 불릴 만큼 강인한 독립 정신을 보여준 인물이다.", "만주에서 활동한 여성 독립운동가", Kingdom.JAPANESE_COLONY, PersonType.INDEPENDENCE_ACTIVIST, 1919, 1933),

            // ==================================================
            // 대한민국 제1공화국
            // ==================================================

            new Person("이승만", "대한민국 임시정부의 초대 대통령을 지냈으며, 광복 이후 남한의 정치 지도자로 활동했다. 1948년 대한민국 정부가 수립되면서 초대 대통령에 취임했으며, 냉전 체제 속에서 반공과 한미동맹 강화를 중심으로 국가 운영을 추진했다. 장기 집권을 위해 헌법을 개정하고 대통령 연임을 확대하는 과정에서 정치적 갈등이 심화되었으며, 결국 1960년 4·19 혁명 이후 대통령직에서 하야하고 하와이로 망명했다.", "대한민국 초대 대통령", Kingdom.FIRST_REPUBLIC_OF_KOREA, PersonType.POLITICIAN, 1948, 1960)
    );
        public static Person findByName(String name) {
            if (name == null) return null;
            return PEOPLE.stream()
                    .filter(p -> p.getName().equals(name))
                    .findFirst()
                    .orElse(null);
        }
}
